class AtProtocolAdapter {
  constructor(cell) {
    this.cell = cell;
    this.pds = null;
    this.relay = null;
  }

  async connect(pdsUrl, relayUrl) {
    this.pds = new XRPCClient(pdsUrl);
    this.relay = new FirehoseClient(relayUrl);
    await this.relay.subscribe((event) => this.ingestEvent(event));
  }

  async publish(cellEvent) {
    const record = this.toLexiconRecord(cellEvent);
    await this.pds.createRecord(record);
  }

  ingestEvent(firehoseEvent) {
    const cellEvent = this.fromFirehose(firehoseEvent);
    this.cell.append(cellEvent);
  }

  toLexiconRecord(cellEvent) { /* translate */ }
  fromFirehose(firehoseEvent) { /* translate */ }
}

class DIDResolver {
  constructor() {
    this.resolvers = new Map();
    this.register('plc', new PLCDIDResolver());
    this.register('web', new WebDIDResolver());
  }

  register(method, resolver) {
    this.resolvers.set(method, resolver);
  }

  async resolve(did) {
    const method = did.split(':')[1];
    const resolver = this.resolvers.get(method);
    if (!resolver) throw new Error(`Unsupported DID method: ${method}`);
    return resolver.resolve(did);
  }
}
